using System;
using UnityEngine;

namespace LangTroTan.Presentation
{
    // Registry of authored Sơn Môn art (Blender architecture kit + Quaternius CC0 nature), generated by
    // Assets/Editor/SonMonKitBuilder.cs and loaded from Resources/SonMon/SonMonKit. Presentation only:
    // positions, footprints and every gameplay decision still come from the authoritative server.
    public sealed class SonMonKit : ScriptableObject
    {
        [Serializable]
        public struct BuildingEntry
        {
            public string type;
            public GameObject prefab;
        }

        public BuildingEntry[] buildings = Array.Empty<BuildingEntry>();
        public GameObject[] resourceTrees = Array.Empty<GameObject>();
        public GameObject[] resourceRocks = Array.Empty<GameObject>();
        public GameObject environment;
        public GameObject spiritDeer;  // Bạch Ngọc Linh Lộc, visual stand-in for server deer nodes
        public GameObject disciple;    // single disciple prototype (awaiting visual approval)
        public Material daySky, nightSky, dawnSky;

        [Serializable]
        public struct GlowEntry
        {
            public Material material;
            [ColorUsage(false, true)] public Color baseEmission;
        }

        // Emissive kit materials (lantern paper, spirit glow, formations) brightened at dusk and night.
        public GlowEntry[] glowMaterials = Array.Empty<GlowEntry>();

        // Unlit cloud sea: tinted by time of day so it does not glare at night.
        public Material cloudMaterial;
        public Color cloudDayColor = Color.white;
        public Color[] seasonLeafTint = { new Color(.92f, 1f, .9f), Color.white, new Color(1.25f, .72f, .42f), new Color(.88f, .95f, 1f) };

        const string ResourcePath = "SonMon/SonMonKit";
        static SonMonKit cached;
        static bool attempted;

        public static SonMonKit Instance
        {
            get
            {
                if (!attempted)
                {
                    cached = Resources.Load<SonMonKit>(ResourcePath);
                    attempted = true;
                }
                return cached;
            }
        }

        public GameObject BuildingPrefab(string type)
        {
            foreach (var entry in buildings)
                if (entry.type == type && entry.prefab != null)
                    return entry.prefab;
            return null;
        }
    }

    public static class SonMonArt
    {
        static readonly int BaseColor = Shader.PropertyToID("_BaseColor");
        static MaterialPropertyBlock leafBlock;

        // Instantiates the authored model for a server building type under root. Returns false when the
        // kit has no prefab for it, so the caller can fall back to the legacy procedural geometry.
        public static bool TryBuilding(Transform root, string type)
        {
            var prefab = SonMonKit.Instance != null ? SonMonKit.Instance.BuildingPrefab(type) : null;
            if (prefab == null) return false;
            UnityEngine.Object.Instantiate(prefab, root, false).name = prefab.name;
            return true;
        }

        // Harvestable tree node. The seed keeps the species and rotation stable across redraws.
        public static bool TryTree(Transform root, int seed, int season)
        {
            var kit = SonMonKit.Instance;
            if (kit == null || kit.resourceTrees.Length == 0) return false;
            var prefab = kit.resourceTrees[seed % kit.resourceTrees.Length];
            var tree = UnityEngine.Object.Instantiate(prefab, root, false);
            tree.transform.localRotation = Quaternion.Euler(0, seed % 360, 0);
            tree.transform.localScale *= .85f + (seed % 7) * .05f;
            TintLeaves(tree, kit.seasonLeafTint[Mathf.Clamp(season, 0, kit.seasonLeafTint.Length - 1)]);
            return true;
        }

        // Quarry stone node; depleted nodes keep a small rubble rock so the spot stays readable.
        public static bool TryRock(Transform root, int seed, bool full)
        {
            var kit = SonMonKit.Instance;
            if (kit == null || kit.resourceRocks.Length == 0) return false;
            var rock = UnityEngine.Object.Instantiate(kit.resourceRocks[seed % kit.resourceRocks.Length], root, false);
            rock.transform.localRotation = Quaternion.Euler(0, seed % 360, 0);
            rock.transform.localScale *= full ? 1f : .35f;
            return true;
        }

        // Server deer node -> White Jade Spirit Deer. Visual only: the node, its harvesting and its
        // synchronisation are unchanged.
        public static bool TryCreature(Transform root, int seed)
        {
            var kit = SonMonKit.Instance;
            if (kit == null || kit.spiritDeer == null) return false;
            var deer = UnityEngine.Object.Instantiate(kit.spiritDeer, root, false);
            deer.name = kit.spiritDeer.name;
            deer.transform.localRotation = Quaternion.Euler(0, seed % 360, 0);
            return true;
        }

        public static bool TryEnvironment(Transform parent)
        {
            var kit = SonMonKit.Instance;
            if (kit == null || kit.environment == null) return false;
            UnityEngine.Object.Instantiate(kit.environment, parent, false).name = kit.environment.name;
            SonMonSky.Reset();
            if (kit.daySky != null) RenderSettings.skybox = kit.daySky;
            return true;
        }

        // Drives sun, sky, ambient, fog, bloom and emissive glow from the server's spatial clock.
        public static bool ApplyTimeOfDay(float phase, int season, bool night, string weather, Light sun, Camera cam, float blend)
        {
            var kit = SonMonKit.Instance;
            if (kit == null || kit.daySky == null) return false;
            SonMonSky.Apply(kit, SonMonSky.Evaluate(kit, phase, season, night, weather), sun, cam, blend);
            return true;
        }

        static void TintLeaves(GameObject tree, Color tint)
        {
            leafBlock ??= new MaterialPropertyBlock();
            foreach (var renderer in tree.GetComponentsInChildren<Renderer>())
            {
                var materials = renderer.sharedMaterials;
                for (int i = 0; i < materials.Length; i++)
                {
                    if (materials[i] == null || !materials[i].name.StartsWith("Leaves")) continue;
                    renderer.GetPropertyBlock(leafBlock, i);
                    leafBlock.SetColor(BaseColor, materials[i].GetColor(BaseColor) * tint);
                    renderer.SetPropertyBlock(leafBlock, i);
                }
            }
        }
    }
}
